// used to refresh the clock number displayed next to Elapsed Time
public void update()
{
// offset used so that when the number of digits increase (1, 10, 100, 1000, etc) it shifts accordingly
int clockTicks = state.getClock().getTime();
convert(clockTicks);
}

// converts the time into a series of digit images
private void convert(int time)
{
ArrayList<Image> list = new ArrayList<Image>();
String s = "" + time;

for (int i = 0; i < s.length(); i++)
{
int digit = Character.digit(s.charAt(i),10);
Image img = ImageLoader.getImageFromURL("/simse/gui/images/layout/n" + digit + ".gif");
list.add(img);
}
timeElapsedDigits = (Image[]) list.toArray(new Image[1]);
repaint();
}
